SELECT jsonb_build_object(
  'identity',jsonb_build_object('db',current_database(),'role',current_user,'readOnly',current_setting('transaction_read_only')),
  'migrations',(SELECT jsonb_agg(to_jsonb(m) ORDER BY migration_name) FROM (SELECT migration_name,checksum,finished_at,rolled_back_at,applied_steps_count FROM meta_ads._prisma_migrations) m),
  'columns',(SELECT jsonb_agg(to_jsonb(c) ORDER BY table_name,ordinal_position) FROM (SELECT table_name,column_name,data_type,is_nullable,column_default,ordinal_position FROM information_schema.columns WHERE table_schema='meta_ads' AND (table_name LIKE 'unified_%' OR table_name IN ('cafe24_order_lines','cafe24_order_api_versions','cafe24_product_rules'))) c),
  'sourceTables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'rowsEstimate',c.reltuples::text) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND (n.nspname='meta_ads' OR (n.nspname='public' AND c.relname IN ('stores','order_items','order_source_signatures','products','canonical_sales_units','sales_unit_cost_settings','sales_unit_cost_snapshots','sales_unit_cost_snapshot_entries','ad_excel_uploads','ad_campaign_daily_costs','daily_fake_purchases','daily_store_summaries','daily_sales_unit_profits','order_sync_states','operations','order_sync_batch_items','order_sync_batches')))),
  'activeTransactions',(SELECT coalesce(jsonb_agg(jsonb_build_object('user',usename,'state',state,'transactionAgeSeconds',extract(epoch from now()-xact_start))), '[]'::jsonb) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND xact_start IS NOT NULL),
  'locks',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'mode',l.mode,'granted',l.granted)),'[]'::jsonb) FROM pg_locks l JOIN pg_class c ON c.oid=l.relation JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='meta_ads' AND c.relname IN ('cafe24_order_lines','cafe24_order_api_versions','cafe24_product_rules'))
) AS metadata;
